using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    private static int ChargedFor(LoyaltyTier tier, int subtotalCents) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    // Returning Bronze customer is charged 9500 cents for a 10000 cents basket
    [Fact]
    public void S1_BronzeCustomerIsChargedNineThousandFiveHundredCents() =>
        Assert.Equal(9500, ChargedFor(LoyaltyTier.Bronze, 10000));

    // Returning Silver customer is charged 9000 cents for a 10000 cents basket
    [Fact]
    public void S2_SilverCustomerIsChargedNineThousandCents() =>
        Assert.Equal(9000, ChargedFor(LoyaltyTier.Silver, 10000));

    // Returning Gold customer is charged 8500 cents for a 10000 cents basket
    [Fact]
    public void S3_GoldCustomerIsChargedEightThousandFiveHundredCents() =>
        Assert.Equal(8500, ChargedFor(LoyaltyTier.Gold, 10000));

    // Returning Bronze customer is charged 7 cents for a 7 cents basket
    [Fact]
    public void S4_BronzeCustomerIsChargedSevenCentsForSevenCentBasket() =>
        Assert.Equal(7, ChargedFor(LoyaltyTier.Bronze, 7));
}

